// ── Themes ──────────────────────────────────────────────────────────
// Every entry has a matching `[data-theme="id"]` token block in
// globals.css. `base` classifies each theme dark/light — it drives the
// isLight-derived neutrals below AND the `data-base` attribute that the
// generic light-mode CSS keys on. `swatch` = [bg, accent, signal] dots
// shown in the picker, sampled from the theme's own palette.
const THEMES = [
  // MARIO is the house default (server-rendered in layout.tsx) — overworld
  // first, its underground twin WARP right behind it.
  { id: "mario",  label: "MARIO",   glyph: "🍄", base: "light", swatch: ["#5c94fc", "#e52521", "#fbd000"] },
  { id: "warp",   label: "WARP",    glyph: "▦", base: "dark",  swatch: ["#050712", "#2fb1f0", "#fbd000"] },
  { id: "dark",   label: "GLASS",   glyph: "◆", base: "dark",  swatch: ["#07070d", "#a78bfa", "#34d399"] },
  { id: "light",  label: "RAINBOW", glyph: "🌈", base: "light", swatch: ["#fffdf7", "#c026d3", "#059669"] },
  { id: "matrix", label: "MATRIX",  glyph: "▚", base: "dark",  swatch: ["#010502", "#00ff7f", "#4defc9"] },
  { id: "neon",   label: "NEON",    glyph: "◢", base: "dark",  swatch: ["#0a0416", "#ff2da0", "#0ff0d4"] },
  { id: "ember",  label: "EMBER",   glyph: "◉", base: "dark",  swatch: ["#0c0603", "#ff9e2c", "#ffd75e"] },
  { id: "abyss",  label: "ABYSS",   glyph: "≋", base: "dark",  swatch: ["#030b18", "#38bdf8", "#2dd4bf"] },
  { id: "paper",  label: "PAPER",   glyph: "▤", base: "light", swatch: ["#f7f2e9", "#9a5b2c", "#15803d"] },
  { id: "win95",  label: "WIN95",   glyph: "▣", base: "light", swatch: ["#c0c0c0", "#000080", "#008000"] },
] as const;
type ThemeId = (typeof THEMES)[number]["id"];
const THEME_IDS = THEMES.map((t) => t.id) as readonly string[];
const themeBase = (id: string): "dark" | "light" =>
  THEMES.find((t) => t.id === id)?.base ?? "dark";

// ── Header control chips ────────────────────────────────────────────
// HUB · TASKS · ASK · theme · SPLIT, the console's own controls, all live
// in one cluster at the right end of the header. Symbol only —
// five words of chrome crowded the row and said little the glyph doesn't;
// the name (and what it does) rides in the data-tip that pops on hover.
const HDR_CHIP_CLASS =
  "hdr-chip shrink-0 inline-flex items-center justify-center gap-1 rounded my-0.5 transition-all focus-ring";
const hdrChipStyle = (active: boolean, color: string): React.CSSProperties => ({
  // Sized for the glyph inside, not the other way round: at 24px the symbols
  // were squinting-small on a desktop screen, which is what made this cluster
  // read as decoration instead of controls.
  height: 30,
  minWidth: 34,
  padding: "0 7px",
  cursor: "pointer",
  color: active ? color : "var(--text-tertiary)",
  background: active ? `color-mix(in srgb, ${color} 12%, transparent)` : "transparent",
  border: `1px solid ${active ? `color-mix(in srgb, ${color} 40%, transparent)` : "var(--border-color)"}`,
});

function HeaderChip({
  tip,
  label,
  color,
  active = false,
  badge = null,
  className = "",
  onClick,
  children,
}: {
  /** The hover popup — say what it opens, not just what it's called. */
  tip: string;
  /** Screen-reader name (the button has no text). */
  label: string;
  color: string;
  active?: boolean;
  badge?: number | null;
  className?: string;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      onClick={onClick}
      className={`${HDR_CHIP_CLASS} ${className}`}
      style={hdrChipStyle(active, color)}
      data-tip={tip}
      aria-label={label}
      aria-pressed={active}
    >
      <span className="inline-flex" style={{ color }}>{children}</span>
      {badge != null && badge > 0 && (
        <span className="font-mono text-[9px] leading-none" style={{ color: active ? color : "var(--text-tertiary)" }}>
          {badge}
        </span>
      )}
    </button>
  );
}

// ── Panel tabs ──────────────────────────────────────────────────────
// One segmented control for every tab strip in the account panel —
// USER/AGENT/COMPUTE and the sub-strips under them. Pills in a recessed
// track rather than the old flat underline: the selected tab reads as
// raised in its own accent, and the unselected ones answer to the mouse
// instead of sitting dead until clicked.
type PanelTab<T extends string> = {
  id: T;
  label: string;
  glyph: string;
  accent: string;
  badge?: number | null;
  title?: string;
};

function PanelTabs<T extends string>({
  tabs,
  value,
  onChange,
  ariaLabel,
  border,
  tint,
  size = "md",
}: {
  tabs: PanelTab<T>[];
  value: T;
  onChange: (id: T) => void;
  ariaLabel: string;
  /** Theme-resolved hairline under the strip (light skins need it softer). */
  border: string;
  /** Sub-strips wash their whole section's accent behind the pills. */
  tint?: string;
  /** md = top strip, sm = the sub-strip nested under it. */
  size?: "md" | "sm";
}) {
  const md = size === "md";
  return (
    <div
      className={`flex items-stretch gap-1 shrink-0 ${md ? "px-2 py-2" : "px-2 py-1.5"}`}
      style={{
        borderBottom: `1px solid ${border}`,
        background: tint
          ? `linear-gradient(180deg, color-mix(in srgb, ${tint} 7%, transparent), transparent)`
          : "color-mix(in srgb, var(--border-color) 18%, transparent)",
      }}
      role="tablist"
      aria-label={ariaLabel}
    >
      {tabs.map((t) => {
        const on = t.id === value;
        return (
          <button
            key={t.id}
            onClick={() => onChange(t.id)}
            className={`flex-1 min-w-0 flex items-center justify-center gap-1.5 rounded-md transition-all focus-ring ${
              md ? "px-2 py-1.5 text-[10px]" : "px-2 py-1 text-[9.5px]"
            } font-bold uppercase tracking-[0.12em]`}
            style={{
              color: on ? t.accent : "var(--text-tertiary)",
              border: `1px solid ${on ? `color-mix(in srgb, ${t.accent} 34%, transparent)` : "transparent"}`,
              background: on
                ? `linear-gradient(180deg, color-mix(in srgb, ${t.accent} 20%, transparent), color-mix(in srgb, ${t.accent} 8%, transparent))`
                : "transparent",
              boxShadow: on ? `0 4px 14px -10px ${t.accent}, inset 0 1px 0 color-mix(in srgb, ${t.accent} 22%, transparent)` : "none",
              textShadow: on ? `0 0 10px color-mix(in srgb, ${t.accent} 45%, transparent)` : "none",
            }}
            onMouseEnter={(e) => {
              if (on) return;
              e.currentTarget.style.color = "var(--text-secondary)";
              e.currentTarget.style.background = `color-mix(in srgb, ${t.accent} 8%, transparent)`;
            }}
            onMouseLeave={(e) => {
              if (on) return;
              e.currentTarget.style.color = "var(--text-tertiary)";
              e.currentTarget.style.background = "transparent";
            }}
            title={t.title}
            aria-selected={on}
            role="tab"
          >
            <span aria-hidden className="shrink-0" style={{ opacity: on ? 1 : 0.5 }}>{t.glyph}</span>
            <span className="truncate">{t.label}</span>
            {t.badge != null && (
              <span
                className="font-mono text-[9px] px-1 rounded-full leading-[13px] shrink-0"
                style={{
                  color: t.accent,
                  border: `1px solid color-mix(in srgb, ${t.accent} 35%, transparent)`,
                  background: `color-mix(in srgb, ${t.accent} 10%, transparent)`,
                }}
              >
                {t.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

// ── Models ──────────────────────────────────────────────────────────
// Specific model IDs the user can pick. Value is what we hand to the CLI's
// --model flag (accepts both family aliases and full names like
// claude-opus-4-7). Keep first item = current default (Fable 5).
const MODEL_OPTIONS = [
  { value: "claude-fable-5",    label: "Fable 5",    family: "fable",  color: "#f472b6" },
  { value: "claude-opus-5",     label: "Opus 5.0",   family: "opus",   color: "#ddd6fe" },
  { value: "claude-opus-4-8",   label: "Opus 4.8",   family: "opus",   color: "#c4b5fd" },
  { value: "claude-opus-4-7",   label: "Opus 4.7",   family: "opus",   color: "#a78bfa" },
  { value: "claude-opus-4-6",   label: "Opus 4.6",   family: "opus",   color: "#9f7aea" },
  { value: "claude-sonnet-4-6", label: "Sonnet 4.6", family: "sonnet", color: "#60a5fa" },
  { value: "claude-sonnet-4-5", label: "Sonnet 4.5", family: "sonnet", color: "#3b82f6" },
  { value: "claude-haiku-4-5",  label: "Haiku 4.5",  family: "haiku",  color: "#34d399" },
];

// Legacy aliases (saved by older builds / older jobs) → upgraded value.
// Family aliases resolve to the newest of that family. `fable` now resolves to
// the live Claude Fable 5 model (Mythos access is generally available).
const MODEL_ALIAS_UPGRADE: Record<string, string> = {
  opus: "claude-opus-5",
  sonnet: "claude-sonnet-4-6",
  haiku: "claude-haiku-4-5",
  fable: "claude-fable-5",
};

// Map any stored/legacy model string to a currently-selectable model value,
// falling back to the default when it's unknown or gated. Mirrors the saved-
// model restore guard so replays/edits never resurrect an unavailable model.
function normalizeModelValue(m: string): string {
  if (!m) return MODEL_OPTIONS[0].value;
  const upgraded = MODEL_ALIAS_UPGRADE[m] || m;
  return MODEL_OPTIONS.some(o => o.value === upgraded) ? upgraded : MODEL_OPTIONS[0].value;
}

// Pretty label for any model string (handles legacy aliases too).
function modelLabel(m: string): string {
  if (!m) return "—";
  const chip = MODEL_OPTIONS.find(o => o.value === m);
  if (chip) return chip.label;
  if (m === "opus") return "Opus 4.6";       // historical default
  if (m === "sonnet") return "Sonnet 4.5";   // historical default
  if (m === "haiku") return "Haiku 4.5";
  return m;
}

