const AGENT_MOD_COLOR = "#60a5fa";

// Which agent ran a job. Every task carries the backend that produced it;
// rows written before the column existed default to claude.
function agentMeta(value?: string) {
  return AGENT_MODS.find(a => a.value === (value || "claude")) || AGENT_MODS[0];
}

