  const [depositBusy, setDepositBusy] = useState(false);
  const [depositMsg, setDepositMsg] = useState<string | null>(null);
  // This module's credit balance (GET /credits): the chain module's Market
  // credit token held by YOUR wallet, plus owner grants, minus what this
  // module metered. Dollars all the way down.
  const [buildCredits, setBuildCredits] = useState<any | null>(null);
  // Credits as a short label — always money, so always "$". Sub-cent balances
  // keep their digits; a fraction of a cent shouldn't round away to "$0".
  const creditsLabel = useMemo(() => {
    const usd6 = buildCredits?.account?.usd6;
    if (usd6 == null) return null;
    const n = Number(usd6) / 1e6;
    if (!Number.isFinite(n)) return null;
    const amt = n === 0 ? "$0" : n < 0.01 ? `$${n.toFixed(4)}` : `$${n.toFixed(2)}`;
    return { amt, sym: "USD", text: amt, empty: n === 0 };
  }, [buildCredits]);
  // Saved agent frameworks — named snapshots of the whole setup above.
  const [frameworks, setFrameworks] = useState<AgentFramework[]>([]);
  const [fwSaveOpen, setFwSaveOpen] = useState(false);
  const [fwSaveName, setFwSaveName] = useState("");
  const fwSaveInputRef = useRef<HTMLInputElement | null>(null);
